INSERT INTO public.notes (id, author_id, author_name, author_role, author_avatar, author_section, is_public, target_type, target_id, target_name, content, priority) VALUES
('note-1788946602168-0r59', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'squadra', '58909', 'Castellarano', 'Squadra neopromossa tramite ripescaggi, squadra con molti giocatori esperti e qualche giovane', 'LOW'),
('note-1788946232433-1asn', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7282236', 'Salvatore Ferrara (Castellarano)', 'Attaccante estremamente fisico. Cerca il contatto e lo scontro, da attenzionare nella coppia con Zucchini.', 'NORMAL'),
('note-1788946099420-iduk', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7771604', 'Luca Leonardi (Castellarano)', 'Ex Sasso Marconi, attaccante esperto e di categoria', 'NORMAL'),
('note-1788945917435-buvx', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7249588', 'Raman Yussif Chibsah (Castellarano)', 'Calciatore con 94 presenze in Serie A (Frosinone, Sassuolo, Parma). Possibile leader tecnico e morale della squadra', 'NORMAL'),
('note-1788945300911-8s5d', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7765029', 'Alì Molossi (Ars Et Labor Ferrara)', 'Centrocampista ex Mezzolara, calciatore fisico e onnipresente in mezzo al campo. Di base corretto nei modi e nei toni.', 'NORMAL'),
('note-1788945010042-djfb', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7279022', 'Manuel Ricci (Ars Et Labor Ferrara)', 'Calciatore polemico, aggressivo nei modi e nei toni sia con AE che sopratutto con gli avversari. Provocatore, trash talking per cercare scontri e diverbi. Estremamente plateale. Da evitare come la peste, starci lontano il più possibile e cogliere l''occasione per tamponarlo. Un ammonizione lo rende immediatamente più attento e pacato', 'HIGH'),
('note-1788944818685-sar4', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7265925', 'Simone Mazzali (Ars Et Labor Ferrara)', 'Terzino sinistro di spinta, tende a sovrapporsi e a creare superiorità numerica sempre senza palla aggredendo la profondità', 'NORMAL'),
('note-1788944747091-jzh1', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '10032021', 'Leonardo Mazza (Ars Et Labor Ferrara)', 'Play e fulcro del gioco spallino, baricentro basso e molto dinamico. Affronta gli avversari in mezzo al campo e ricopre compiti più difensivi', 'NORMAL'),
('note-1788944567051-lgav', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7766441', 'Andrea Dall''Ara (Ars Et Labor Ferrara)', 'Capitano della squadra, leader incisivo ma pacato nei modi. Permette di creare un dialogo costruttivo ed efficace. Tendenzialmente non plateale, si tratta però di un giocatore esperto che può cambiare atteggiamento a seconda delle necessità. Da responsabilizzare per far si che gli altri calciatori stiano lontani', 'NORMAL'),
('note-1788944268699-oejp', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'squadra', '1281681', 'Ars Et Labor Ferrara', 'Squadra in gran parte rinnovata, nuova dirigenza che ha investito in calciatori più esperti e pronti per la categoria. Sono state date molte più responsabilità a Parlato che ha modellato la squadra secondo le sue esigenze. Hanno pareggiato 0-0 la prima in casa contro una neopromossa, il che ha portato un pò di pressione all''ambiente. L''obbiettivo è quello di vincere il campionato, si dovranno contendere il primato con la Vianese', 'LOW'),
('note-1788876539281-d9ow', 'samueleromini', 'Samuele Romini', 'AE', '', '', true, 'giocatore', '7242333', 'Gianluca Zucchini (Ars Et Labor Ferrara)', 'Calciatore molto aggressivo, interventi in ritardo e veementi, specialemente con l''attaccante spalle alla porta. Scappa sempre prima che AE si avvicini (tagliagli la strada dopo il fischio). Provocatore con gli avversari, cerca scontro fisico', 'HIGH')
